CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`username` text NOT NULL,`email` text NOT NULL,`password` text NOT NULL,`age` integer,`bio` text,`avatar_url` text,`profile_type` text,`gender` text,`interests` text,`location_lat` real,`location_long` real,`is_premium` numeric DEFAULT false,`is_private` numeric DEFAULT false);
CREATE TABLE sqlite_sequence(name,seq);
CREATE UNIQUE INDEX `idx_users_email` ON `users`(`email`);
CREATE UNIQUE INDEX `idx_users_username` ON `users`(`username`);
CREATE INDEX `idx_users_deleted_at` ON `users`(`deleted_at`);
CREATE TABLE `chats` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime);
CREATE INDEX `idx_chats_deleted_at` ON `chats`(`deleted_at`);
CREATE TABLE `user_chats` (`chat_id` integer,`user_id` integer,PRIMARY KEY (`chat_id`,`user_id`),CONSTRAINT `fk_user_chats_chat` FOREIGN KEY (`chat_id`) REFERENCES `chats`(`id`),CONSTRAINT `fk_user_chats_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `photos` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`url` text NOT NULL,`is_private` numeric DEFAULT false,CONSTRAINT `fk_users_photos` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE INDEX `idx_photos_deleted_at` ON `photos`(`deleted_at`);
CREATE TABLE `posts` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`text` text,`image_url` text,CONSTRAINT `fk_users_posts` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE INDEX `idx_posts_deleted_at` ON `posts`(`deleted_at`);
CREATE TABLE `comments` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`text` text NOT NULL,`photo_id` integer,`post_id` integer,CONSTRAINT `fk_users_comments` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_photos_comments` FOREIGN KEY (`photo_id`) REFERENCES `photos`(`id`),CONSTRAINT `fk_posts_comments` FOREIGN KEY (`post_id`) REFERENCES `posts`(`id`));
CREATE INDEX `idx_comments_deleted_at` ON `comments`(`deleted_at`);
CREATE TABLE `likes` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`liked_id` integer,CONSTRAINT `fk_users_likes` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE UNIQUE INDEX `idx_user_liked` ON `likes`(`user_id`,`liked_id`);
CREATE INDEX `idx_likes_deleted_at` ON `likes`(`deleted_at`);
CREATE TABLE `post_likes` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`post_id` integer,CONSTRAINT `fk_posts_likes` FOREIGN KEY (`post_id`) REFERENCES `posts`(`id`));
CREATE UNIQUE INDEX `idx_post_like` ON `post_likes`(`user_id`,`post_id`);
CREATE INDEX `idx_post_likes_deleted_at` ON `post_likes`(`deleted_at`);
CREATE TABLE `photo_likes` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`photo_id` integer,CONSTRAINT `fk_photos_likes` FOREIGN KEY (`photo_id`) REFERENCES `photos`(`id`));
CREATE UNIQUE INDEX `idx_photo_like` ON `photo_likes`(`user_id`,`photo_id`);
CREATE INDEX `idx_photo_likes_deleted_at` ON `photo_likes`(`deleted_at`);
CREATE TABLE `comment_likes` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`user_id` integer,`comment_id` integer,CONSTRAINT `fk_comments_likes` FOREIGN KEY (`comment_id`) REFERENCES `comments`(`id`));
CREATE UNIQUE INDEX `idx_comment_like` ON `comment_likes`(`user_id`,`comment_id`);
CREATE INDEX `idx_comment_likes_deleted_at` ON `comment_likes`(`deleted_at`);
CREATE TABLE `blocks` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`blocker_id` integer,`blocked_id` integer,CONSTRAINT `fk_users_sent_blocks` FOREIGN KEY (`blocker_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_users_received_blocks` FOREIGN KEY (`blocked_id`) REFERENCES `users`(`id`));
CREATE UNIQUE INDEX `idx_block` ON `blocks`(`blocker_id`,`blocked_id`);
CREATE INDEX `idx_blocks_deleted_at` ON `blocks`(`deleted_at`);
CREATE TABLE `messages` (`id` integer PRIMARY KEY AUTOINCREMENT,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`chat_id` integer,`sender_id` integer,`content` text,`image_url` text,`sent_at` datetime,CONSTRAINT `fk_chats_messages` FOREIGN KEY (`chat_id`) REFERENCES `chats`(`id`));
CREATE INDEX `idx_messages_deleted_at` ON `messages`(`deleted_at`);
